changeSet.sql:
ALTER TABLE nexus.pdf_pipeline
    ADD COLUMN pipeline_id BIGINT GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE nexus.pdf_pipeline
    ADD COLUMN keyed_by TEXT NOT NULL DEFAULT 'content_hash';
ALTER TABLE nexus.pdf_pipeline
    ADD CONSTRAINT pdf_pipeline_keyed_by_chk CHECK (keyed_by IN ('content_hash', 'document'));
ALTER TABLE nexus.pdf_pipeline DROP CONSTRAINT pdf_pipeline_pk;
ALTER TABLE nexus.pdf_pipeline
    ADD CONSTRAINT pdf_pipeline_pk PRIMARY KEY (tenant_id, pipeline_id);
ALTER TABLE nexus.pdf_pipeline
    ADD CONSTRAINT pdf_pipeline_document_uq UNIQUE (tenant_id, content_hash, collection, pdf_path);
CREATE UNIQUE INDEX pdf_pipeline_legacy_uq
    ON nexus.pdf_pipeline (tenant_id, content_hash)
    WHERE keyed_by = 'content_hash';

changeSet.rollback:
ALTER TABLE nexus.pdf_pipeline NO FORCE ROW LEVEL SECURITY;
DELETE FROM nexus.pdf_pipeline WHERE pipeline_id NOT IN (SELECT DISTINCT ON (tenant_id, content_hash) pipeline_id FROM nexus.pdf_pipeline ORDER BY tenant_id, content_hash, (keyed_by <> 'content_hash'), pipeline_id);
ALTER TABLE nexus.pdf_pipeline FORCE ROW LEVEL SECURITY;
DROP INDEX nexus.pdf_pipeline_legacy_uq;
ALTER TABLE nexus.pdf_pipeline DROP CONSTRAINT pdf_pipeline_document_uq;
ALTER TABLE nexus.pdf_pipeline DROP CONSTRAINT pdf_pipeline_pk;
ALTER TABLE nexus.pdf_pipeline ADD CONSTRAINT pdf_pipeline_pk PRIMARY KEY (tenant_id, content_hash);
ALTER TABLE nexus.pdf_pipeline DROP CONSTRAINT pdf_pipeline_keyed_by_chk;
ALTER TABLE nexus.pdf_pipeline DROP COLUMN keyed_by;
ALTER TABLE nexus.pdf_pipeline DROP COLUMN pipeline_id;

changeSet.sql:
ALTER TABLE nexus.pdf_pages  ADD COLUMN pipeline_id BIGINT;
ALTER TABLE nexus.pdf_chunks ADD COLUMN pipeline_id BIGINT;

ALTER TABLE nexus.pdf_pipeline NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.pdf_pages    NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.pdf_chunks   NO FORCE ROW LEVEL SECURITY;

UPDATE nexus.pdf_pages w
   SET pipeline_id = p.pipeline_id
  FROM nexus.pdf_pipeline p
 WHERE p.tenant_id = w.tenant_id
   AND p.content_hash = w.content_hash;

UPDATE nexus.pdf_chunks w
   SET pipeline_id = p.pipeline_id
  FROM nexus.pdf_pipeline p
 WHERE p.tenant_id = w.tenant_id
   AND p.content_hash = w.content_hash;

DELETE FROM nexus.pdf_pages  WHERE pipeline_id IS NULL;
DELETE FROM nexus.pdf_chunks WHERE pipeline_id IS NULL;

ALTER TABLE nexus.pdf_chunks   FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.pdf_pages    FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.pdf_pipeline FORCE ROW LEVEL SECURITY;

ALTER TABLE nexus.pdf_pages  ALTER COLUMN pipeline_id SET NOT NULL;
ALTER TABLE nexus.pdf_chunks ALTER COLUMN pipeline_id SET NOT NULL;

ALTER TABLE nexus.pdf_pages DROP CONSTRAINT pdf_pages_pk;
ALTER TABLE nexus.pdf_pages
    ADD CONSTRAINT pdf_pages_pk PRIMARY KEY (tenant_id, pipeline_id, page_index);
ALTER TABLE nexus.pdf_pages
    ADD CONSTRAINT pdf_pages_pipeline_fk FOREIGN KEY (tenant_id, pipeline_id)
        REFERENCES nexus.pdf_pipeline (tenant_id, pipeline_id) ON DELETE CASCADE;
ALTER TABLE nexus.pdf_pages DROP COLUMN content_hash;

ALTER TABLE nexus.pdf_chunks DROP CONSTRAINT pdf_chunks_pk;
ALTER TABLE nexus.pdf_chunks
    ADD CONSTRAINT pdf_chunks_pk PRIMARY KEY (tenant_id, pipeline_id, chunk_index);
ALTER TABLE nexus.pdf_chunks
    ADD CONSTRAINT pdf_chunks_pipeline_fk FOREIGN KEY (tenant_id, pipeline_id)
        REFERENCES nexus.pdf_pipeline (tenant_id, pipeline_id) ON DELETE CASCADE;
ALTER TABLE nexus.pdf_chunks DROP COLUMN content_hash;

changeSet.rollback:
ALTER TABLE nexus.pdf_pages  ADD COLUMN content_hash TEXT;
ALTER TABLE nexus.pdf_chunks ADD COLUMN content_hash TEXT;
ALTER TABLE nexus.pdf_pipeline NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.pdf_pages    NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.pdf_chunks   NO FORCE ROW LEVEL SECURITY;
DELETE FROM nexus.pdf_pages WHERE pipeline_id NOT IN (SELECT DISTINCT ON (tenant_id, content_hash) pipeline_id FROM nexus.pdf_pipeline ORDER BY tenant_id, content_hash, (keyed_by <> 'content_hash'), pipeline_id);
DELETE FROM nexus.pdf_chunks WHERE pipeline_id NOT IN (SELECT DISTINCT ON (tenant_id, content_hash) pipeline_id FROM nexus.pdf_pipeline ORDER BY tenant_id, content_hash, (keyed_by <> 'content_hash'), pipeline_id);
UPDATE nexus.pdf_pages w SET content_hash = p.content_hash FROM nexus.pdf_pipeline p WHERE p.tenant_id = w.tenant_id AND p.pipeline_id = w.pipeline_id;
UPDATE nexus.pdf_chunks w SET content_hash = p.content_hash FROM nexus.pdf_pipeline p WHERE p.tenant_id = w.tenant_id AND p.pipeline_id = w.pipeline_id;
ALTER TABLE nexus.pdf_chunks   FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.pdf_pages    FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.pdf_pipeline FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.pdf_pages  ALTER COLUMN content_hash SET NOT NULL;
ALTER TABLE nexus.pdf_chunks ALTER COLUMN content_hash SET NOT NULL;
ALTER TABLE nexus.pdf_pages DROP CONSTRAINT pdf_pages_pipeline_fk;
ALTER TABLE nexus.pdf_pages DROP CONSTRAINT pdf_pages_pk;
ALTER TABLE nexus.pdf_pages ADD CONSTRAINT pdf_pages_pk PRIMARY KEY (tenant_id, content_hash, page_index);
